func greet(name: String = "Guest") {
    print("Hello, \(name)")
}
greet()
greet(name: "Mina")

func total(_ scores: Int...) -> Int {
    var sum = 0
    for score in scores { sum += score }
    return sum
}
print(total(3, 8, 5))

func addBonus(to score: inout Int) {
    score += 10
}
var score = 80
addBonus(to: &score)
print(score)

